#!/usr/bin/env python3\n"""Base64 payload extractor.\n\nReads binary data from a file passed as argument or from stdin,\nsearches for Base64-encoded strings, decodes them, and prints a JSON\nwith the list of decoded payloads (hex representation)."""\nimport sys, re, base64, json\n\ndef read_input():\n    if len(sys.argv) > 1:\n        with open(sys.argv[1], 'rb') as f:\n            return f.read()\n    else:\n        return sys.stdin.buffer.read()\n\ndef find_base64(data):\n    pattern = re.compile(rb'(?:[A-Za-z0-9+/]{4}){2,}(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?')\n    return pattern.findall(data)\n\ndef decode_payloads(matches):\n    decoded = []\n    for m in matches:\n        try:\n            raw = base64.b64decode(m, validate=True)\n            decoded.append(raw.hex())\n        except Exception:\n            continue\n    return decoded\n\ndef main():\n    data = read_input()\n    matches = find_base64(data)\n    payloads = decode_payloads(matches)\n    result = {"base64_payloads": payloads}\n    print(json.dumps(result, ensure_ascii=False))\n\nif __name__ == "__main__":\n    main()